  for (i = 0; i < ctx.train.length; i++)
    parts.push(G.gkey(ctx.train[i][0]), G.gkey(ctx.train[i][1]));
  parts.push("|");
  for (i = 0; i < ctx.test_inputs.length; i++) parts.push(G.gkey(ctx.test_inputs[i]));
  return parts.join("~");
