          res.push(_h("mark#" + c + "_pad" + pads[j][0] + pads[j][1],
                      (function (pr, pc) { return function (g) { return _markedRect(g, bg, c, true, pr, pc); }; })(pads[j][0], pads[j][1]),
                      4.8));
        var segs = ["m8", "m4"];
