    v[IX.container_color] = (cont >= 0 && cont < objs.length) ? objs[cont].color : -1;
    v[IX.near_color] = extra.near[index];
    v[IX.major_color] = extra.major;
    v[IX.minor_color] = extra.minor;
    v[IX.bg] = bg;
    v[IX.touching] = extra.touch[index];
